	@Test
	void requestCancellationIsIdempotentWhileEvaluationRemainsOpen() {
		NativeLmdbQuerySource source = new StubSource();
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("value", 0), null);
		layout.freeze(List.of("value"));
		NativeGroupIteration iteration = new NativeGroupIteration(source, SlotPlan.empty(), layout, new int[0],
				new AggregateSpec[0], false, EmptyBindingSet.getInstance(), null, null, false, null);

		assertThat(iteration).isInstanceOf(CooperativeCancellation.class);
		CooperativeCancellation cancellation = (CooperativeCancellation) (Object) iteration;
		assertThat(cancellation.requestCancellation()).isTrue();
		assertThat(cancellation.requestCancellation()).isTrue();
		iteration.close();
		assertThat(cancellation.requestCancellation()).isFalse();
	}

	@Test
	void closeStopsInFlightAggregationAtNextPoll() throws Exception {
		CountDownLatch firstRowEntered = new CountDownLatch(1);
		CountDownLatch releaseFirstRow = new CountDownLatch(1);
		AtomicInteger nextCalls = new AtomicInteger();
		AtomicInteger closeCalls = new AtomicInteger();
		NativeLmdbQuerySource source = new StubSource();
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("value", 0), null);
		layout.freeze(List.of("value"));
		SlotPlan plan = new ControlledPlan(firstRowEntered, releaseFirstRow, nextCalls, closeCalls);
		AggregateSpec[] aggregates = { AggregateSpec.slot("count", 0, false, AggKind.COUNT) };
		NativeGroupIteration iteration = new NativeGroupIteration(source, plan, layout, new int[0], aggregates, false,
				EmptyBindingSet.getInstance(), null, null, false, null);
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<List<BindingSet>> worker = executor.submit(() -> iteration.evaluateSequential(row,
				new AggContext(source, false), LmdbNativeAttemptMetrics.root()));

		try {
			assertThat(firstRowEntered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS))
					.as("the aggregation worker must reach the controlled row before close")
					.isTrue();
			iteration.close();
			releaseFirstRow.countDown();

			ExecutionException failure = assertThrows(ExecutionException.class,
					() -> worker.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS));
			assertThat(failure.getCause()).isInstanceOf(KernelQueryCancelledException.class);
			assertThat(nextCalls)
					.as("close must be observed at the first aggregate poll after the in-flight cursor call returns")
					.hasValue(1);
			assertThat(closeCalls).as("the in-flight cursor must still close exactly once").hasValue(1);
		} finally {
			releaseFirstRow.countDown();
			iteration.close();
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
	}

	private static final class ControlledPlan implements SlotPlan {

		private final CountDownLatch firstRowEntered;
		private final CountDownLatch releaseFirstRow;
		private final AtomicInteger nextCalls;
		private final AtomicInteger closeCalls;

		private ControlledPlan(CountDownLatch firstRowEntered, CountDownLatch releaseFirstRow,
				AtomicInteger nextCalls, AtomicInteger closeCalls) {
			this.firstRowEntered = firstRowEntered;
			this.releaseFirstRow = releaseFirstRow;
			this.nextCalls = nextCalls;
			this.closeCalls = closeCalls;
		}

		@Override
		public RowCursor open(RowState row) {
			return new RowCursor() {
				@Override
				public boolean next() {
					int call = nextCalls.incrementAndGet();
					if (call == 1) {
						firstRowEntered.countDown();
						await(releaseFirstRow);
						row.bind(0, 1L);
						return true;
					}
					throw new AssertionError("aggregate cursor advanced after close was visible at its poll point");
				}

				@Override
				public void close() {
					closeCalls.incrementAndGet();
				}
			};
		}

		@Override
		public long producedMask() {
			return 1L;
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS)) {
				throw new AssertionError("timed out waiting for controlled aggregate release");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError("aggregate worker interrupted while awaiting controlled release", e);
		}
	}

